class OriginalEvaluationTests(unittest.TestCase):
    def test_preparation_preserves_specs_and_refuses_reuse(self):
        with tempfile.TemporaryDirectory() as directory:
            output = Path(directory) / "evaluation"
            prepare(output, "http://127.0.0.1:5173")
            for source in (ROOT / "input/tests").glob("*.ts"):
                self.assertEqual(source.read_bytes(), (output / "tests" / source.name).read_bytes())
            with self.assertRaises(FileExistsError):
                prepare(output, "http://127.0.0.1:5173")

    def test_failed_seed_blocks_all_scenarios(self):
        with tempfile.TemporaryDirectory() as directory:
            output = Path(directory) / "evaluation"
