import type Database from "better-sqlite3";
import type { ApiRequest, ApiResponse } from "./types.js";

function headerValue(headers: Record<string, string | undefined>, name: string): string | undefined {
  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() === name) return value;
  }
  return undefined;
}

function readCookie(header: string | undefined, name: string): string | undefined {
  if (!header) return undefined;

  for (const part of header.split(";")) {
    const separator = part.indexOf("=");
    if (separator === -1) continue;

    const cookieName = part.slice(0, separator).trim();
    if (cookieName !== name) continue;

    return part.slice(separator + 1).trim();
  }

  return undefined;
}

export async function handle(request: ApiRequest, connection: Database.Database): Promise<ApiResponse> {
  const cookieHeader = headerValue(request.headers, "cookie");
  const credential = readCookie(cookieHeader, "session_token");

  if (credential === undefined || credential.length === 0) {
    return { status: 200, body: { authenticated: false } };
  }

  const session = connection
    .prepare(
      'SELECT "Account"."username" AS "username" FROM "Session" INNER JOIN "Account" ON "Account"."id" = "Session"."account_id" WHERE "Session"."credential" = ? LIMIT 1',
    )
    .get(credential) as { username: string } | undefined;

  if (!session) {
    return { status: 200, body: { authenticated: false } };
  }

  return {
    status: 200,
    body: {
      authenticated: true,
      username: session.username,
    },
  };
}

